// AppHeader is APP chrome — it persists across routes and holds global
// affordances (brand, search, account). One per app.
<AppShell header={<AppHeader title="Studio" />}>
  <Region max="content">Route content</Region>
</AppShell>

// PageHeader is CONTENT — it introduces the current route and scrolls away
// with it. One per page, INSIDE the region.
<Region max="content">
  <PageHeader title="Billing" description="Plans, invoices, payment methods." />
</Region>

// ✗ Putting route-specific actions in AppHeader. They then persist onto routes
//   where they mean nothing, and the header becomes a dumping ground.

const browsers = [
	{ browser: "Chrome", visitors: 275 },
	{ browser: "Safari", visitors: 200 },
	{ browser: "Firefox", visitors: 187 },
	{ browser: "Edge", visitors: 173 },
]

<BarChart
	label="Visitors by browser"
	data={browsers}
	index="browser"
	series={[{ key: "visitors", label: "Visitors" }]}
	orientation="horizontal"
	labels="inside"
	yAxis={false}
	grid={false}
/>

// BottomNav is for 3–5 PEER destinations on a small viewport — the mobile
// counterpart to SideNav, not an action bar.

// ✗ Actions. A bottom bar of verbs (Save / Share / Delete) is a toolbar; it
//   competes with the OS gesture area and has no "current" state to show.
// ✗ More than five items. Past that, labels truncate and targets shrink below
//   the 44px floor — use a "More" destination that opens a Sheet.
// ✗ Nested navigation. BottomNav switches top-level sections only; drilling in
//   happens inside the section, with Breadcrumbs or a back affordance.

<AppShell bottomNav={<BottomNav>
  <BottomNavItem label="Home" icon={<Icon name="home" />} active />
  <BottomNavItem label="Search" icon={<Icon name="search" />} />
  <BottomNavItem label="Account" icon={<Icon name="user" />} />
</BottomNav>}>
  <Region max="feed">Route content</Region>
</AppShell>

// Browser is DECORATIVE framing for a screenshot or a demo — it belongs on a
// marketing page, never around your actual app.

<Region max="wide">
  <Browser url="studio.example">
    <img src="/screenshots/editor.png" alt="The editor" />
  </Browser>
</Region>

// ✗ Wrapping live UI in it. The frame implies "this is a picture of software";
//   putting real controls inside makes users hunt for a browser that isn't there.
// ✗ Using it to fake a URL bar for credibility. Show the real product.

const trigger = useCaretTrigger({ triggers: [{ char: "@", allowSpaces: true }, { char: "/", atStart: true }] })
const q = trigger.match?.query.toLowerCase() ?? ""
const commands = trigger.match?.trigger.char === "/"

<ChatComposer fieldRef={trigger.fieldRef} onSend={send} />
<CaretMenu trigger={trigger} label={commands ? "Commands" : "People"} status={!commands && people.length === 0 ? "No one matches" : undefined}>
	{commands
		? slashCommands.filter((c) => c.name.startsWith(q)).map((c) => (
			<CaretMenuItem key={c.name} description={c.hint} onSelect={() => { c.run(); trigger.replace("") }}>/{c.name}</CaretMenuItem>
		))
		: people.filter((p) => p.name.toLowerCase().includes(q)).map((p) => (
			<CaretMenuItem key={p.id} icon={<Avatar size="sm" src={p.avatar} fallback={p.initials} />} onSelect={() => trigger.replace(`@${p.name} `)}>{p.name}</CaretMenuItem>
		))}
</CaretMenu>

const trigger = useCaretTrigger({ triggers: [{ char: "#" }] })
// Fetch from trigger.match?.query yourself, debounced; pass the state as status.
<Textarea ref={trigger.fieldRef} aria-label="Note" />
<CaretMenu trigger={trigger} label="Channels" status={loading ? "Searching…" : channels.length === 0 ? "No channels match" : undefined}>
	{channels.map((c) => <CaretMenuItem key={c.id} onSelect={() => trigger.replace(`#${c.name} `)}>#{c.name}</CaretMenuItem>)}
</CaretMenu>

// Picking the wrong one is the usual mistake:
//
//   Code                   inline, inside a sentence       → `useState`
//   CodeBlock              multi-line, read-only           → an example to study
//   CodeBlock prompt="$"   one line, meant to be COPIED    → an install command

Install with <Code>pnpm add @sableui/react</Code>          {/* ✗ they will want to copy it */}
<CodeBlock prompt="$" code="pnpm add @sableui/react" />   {/* ✓ one line, with a copy button */}

// ColorField only ever EMITS these three shapes:
//   "transparent" | "#rrggbb" | "#rrggbbaa"
// It accepts #rgb and #rgba on paste but never produces them, so a consumer's
// parser has three cases to handle rather than five.
//
// Alpha is omitted when fully opaque — "#3b82f6", never "#3b82f6ff" — so a
// parser written before alpha support keeps reading opaque colours correctly.
// Only enable allowAlpha once your parser and your persisted format accept the
// 8-digit form, or a document saved by a newer build degrades on an older one.

import { parseHex, isTransparent } from "@sableui/react"

const parsed = isTransparent(value) ? null : parseHex(value) // null = not a colour

const [selected, setSelected] = useState<Set<string | number>>(new Set())

<Stack gap={2}>
	{/* Mounted from the start, so a screen reader hears each change. */}
	<span role="status" className="sr-only">{selected.size ? `${selected.size} of ${tickets.length} selected` : ""}</span>
	{selected.size ? (
		<Toolbar aria-label="Bulk actions">
			<span className="text-label-md">{selected.size} of {tickets.length} selected</span>
			<Button size="sm" variant="secondary" onClick={() => resolve(selected)}>Resolve</Button>
		</Toolbar>
	) : null}
	<DataTable
		data={tickets}
		rowKey={(t) => t.id}
		columns={columns}
		selectedKeys={selected}
		onSelectedKeysChange={setSelected}
		rowSelectionLabel={(t) => `Select ${t.subject}`}
		selectAllLabel={(n) => `Select all ${n} tickets shown`}
	/>
</Stack>

const STATUSES = [
