// Phone is DECORATIVE framing for a mobile screenshot on a marketing surface.

<Phone>
  <img src="/screenshots/mobile.png" alt="The mobile app" />
</Phone>

// ✗ Using it to test responsive layout. The frame is a fixed aspect box, not a
//   viewport — media queries inside it key off the real window, so what you see
//   is not what a phone renders. Resize the browser, or use device emulation.
// ✗ Wrapping live, interactive app UI (forms, buttons that act). Same as Browser: the frame says "picture of
//   software", so real controls inside it read as a screenshot that moves. Static composed content is fine.
//   The exception is a clickable iOS prototype: PhoneFrame (@sableui/react/ios/preview)
//   frames a whole phone-sized document in an iframe, where the frame is the device.

const [q, setQ] = useState("")
const results = useMatchHighlight<HTMLUListElement>(q, { selector: "[data-title]" })
const shown = posts.filter((post) => post.title.toLowerCase().includes(q.trim().toLowerCase()))

<SearchInput value={q} onValueChange={setQ} placeholder="Search posts" />
<ul ref={results}>
	{shown.map((post) => (
		<li key={post.id}><span data-title>{post.title}</span></li>
	))}
</ul>

// Arrows move; Enter, Space or a click commits — so whatever the switch costs
// (a confirm, a font load, a reset) happens once, on the pick.
const { themeId, setThemeId, themes, mode } = useSableTheme()
const current = themes.find((theme) => theme.id === themeId)
<DisclosurePicker>
  <DisclosurePickerTrigger aria-label={`Theme: ${current?.label}`} media={current ? <ThemePreview theme={current} mode={mode} size="sm" /> : null}>
    {current?.label}
  </DisclosurePickerTrigger>
  <DisclosurePickerPanel>
    <DisclosurePickerList aria-label="Theme" value={themeId} onValueChange={setThemeId}>
      {themes.map((theme) => (
        <DisclosurePickerOption key={theme.id} value={theme.id} media={<ThemePreview theme={theme} mode={mode} size="sm" />}>
          {theme.label}
        </DisclosurePickerOption>
      ))}
    </DisclosurePickerList>
  </DisclosurePickerPanel>
</DisclosurePicker>

// ✗ `sm:` keys off the VIEWPORT, not this component's container. On a wide
//   screen it does nothing at all for a narrow parent — and this exact
//   workaround, once documented here, is how the cards layout ended up in a
//   256px popover clipping "Default" to "D".
<ThemeSelector className="sm:grid-cols-1" value={themeId} onValueChange={setThemeId} />

// ✓ The cards grid already reflows on its own width (auto-fit, 9rem tracks).
//   For a genuinely narrow surface, change the presentation instead.
<ThemeSelector layout="list" value={themeId} onValueChange={setThemeId} />

// Nest with subtree; folders own their open state via defaultExpanded.
// A row with no onClick toggles when clicked or activated, like a folder in
// a file explorer. Depth is inherited — never computed by hand.
<Tree aria-label="Files" className="max-w-xs">
  <TreeRow
    icon={<Icon name="folder" />}
    toggleLabel="src"
    subtree={
      <>
        <TreeRow icon={<Icon name="file" />} onClick={() => open("index.ts")}>index.ts</TreeRow>
        <TreeRow
          icon={<Icon name="folder" />}
          toggleLabel="components"
          defaultExpanded={false}
          subtree={
            <TreeRow icon={<Icon name="file" />} selected onClick={() => open("button.tsx")}>
              button.tsx
            </TreeRow>
          }
        >
          components
        </TreeRow>
      </>
    }
  >
    src
  </TreeRow>
  <TreeRow icon={<Icon name="file" />} onClick={() => open("README.md")}>README.md</TreeRow>
</Tree>

// A section with nothing in it offers exactly ONE way forward. Not EmptyState:
// that is page-register (px-6 py-12 around a size-12 disc) and in a 240px panel
// it spends 24px of inset and ~96px of height on nothing.
<TreeSection title="Layers">
  <TreeEmpty message="No images yet" action={<TreeAddRow depth={0} label="Add image" />} />
</TreeSection>

// As a drop region — the app owns the drag handlers; TreeEmpty owns the frame
// and sets data-drop-target so a data-[drop-active] style can respond.
<TreeEmpty
  dropTarget
  message="Drop an image"
  data-drop-active={dragging || undefined}
  onDragOver={(e) => { e.preventDefault(); setDragging(true) }}
  onDragLeave={() => setDragging(false)}
  onDrop={handleDrop}
  className="data-[drop-active]:border-primary"
/>

// A layers panel: the arrows select as they move. The row's own onClick is
// the one selection path; Shift+Arrow arrives as a click with shiftKey.
<Tree aria-label="Layers" aria-multiselectable selectionFollowsFocus>
  {layers.map((layer) => (
    <TreeRow
      key={layer.id}
      icon={<Icon name="image-stack" />}
      selected={selection.includes(layer.id)}
      onClick={(event) => (event.shiftKey ? extendTo(layer.id) : selectOnly(layer.id))}
    >
      {layer.name}
    </TreeRow>
  ))}
</Tree>

// A layer with no effects: TreeEmpty at the branch's depth lands on the
// same edge its effect rows would — no hand-computed inset.
<TreeRow depth={0} icon={<Icon name="image-stack" />} toggleLabel="Overlay" subtree={
  <>
    <TreeEmpty message="No effects yet" />
    <TreeAddRow label="Add effect" />
  </>
}>
  Overlay
</TreeRow>

