export function Root({ children }: { children: ReactNode }) {
	return <MotionProvider defaultPolicy="system">{children}</MotionProvider>
}

function ReduceMotionSetting() {
	const { policy, setPolicy } = useMotion()
	return (
		<Switch
			checked={policy === "reduced"}
			onCheckedChange={(on) => setPolicy(on ? "reduced" : "system")}
			aria-label="Reduce motion"
		/>
	)
}

function MotionSetting() {
	const { policy, setPolicy } = useMotion()
	return (
		<ToggleGroup
			appearance="segmented"
			value={[policy === "system" ? "full" : policy]}
			onValueChange={(next) => next[0] && setPolicy(next[0] === "full" ? "system" : (next[0] as "subtle" | "off"))}
			aria-label="Motion"
		>
			<Toggle value="full">Full</Toggle>
			<Toggle value="subtle">Subtle</Toggle>
			<Toggle value="off">Off</Toggle>
		</ToggleGroup>
	)
}

export function Dashboard({ children }: { children: ReactNode }) {
	return <MotionScope level="subtle">{children}</MotionScope>
}

function Drawer({ children }: { children: ReactNode }) {
	return (
		<PresentationProvider value="sheet">
			<div className="sable-surface-popover bg-popover text-popover-foreground">{children}</div>
		</PresentationProvider>
	)
}

export function Root({ children }: { children: ReactNode }) {
